sys_script_include.script:
var LoanStats = Class.create();
LoanStats.prototype = {
    initialize: function() {},

	// Most-borrowed assets: COUNT grouped by asset, done in the database
	mostBorrowed: function (limit){
		var ga = new GlideAggregate('x_1611922_asset_0_request');
		ga.addAggregate('COUNT');
		ga.groupBy('asset');
		ga.query();
		var out = [];
		while(ga.next()){
			out.push({ asset: ga.asset.getDisplayValue(), loans: parseInt(ga.getAggregate('COUNT'), 10) });
        }
        out.sort(function (a, b) { return b.loans - a.loans; });
        return out.slice(0, limit || 5);
	},
    type: 'LoanStats'
};
